type Obj = Record<string, unknown>;
type Db = Parameters<Parameters<typeof transaction>[0]>[0];
type Kind = 'text' | 'date' | 'num' | 'bool';
type UserId = string | null;

interface Field {
  key: string;
  col: string;
  kind: Kind;
  req: boolean;
  hidden: boolean;
}

interface Spec {
  table: string;
  idCol: string;
  idKey: string;
  type: string;
  code: string;
  label: string;
  fields: Field[];
  range?: [string, string];
